<script lang="ts">
  import { onMount } from 'svelte';
  import { createApiClient } from '$lib/api/client';
  import type { CatalogKind, CatalogRecord } from './types';
  let { kind, title }: { kind: CatalogKind; title: string } = $props();
  let records = $state<CatalogRecord[] | null>(null); let selected = $state<CatalogRecord | null>(null); let error = $state<string | null>(null); let loading = $state(true); let saving = $state(false); let search = $state(''); let draft = $state({ name: '', description: '', alignment: 'NEUTRAL', rarity: 'COMMON', cost: 0, default_charges: 0, any_ability: false, hour_duration: 0 }); const api = createApiClient();
  let abilityOptions = $state<CatalogRecord[]>([]);
  let perkOptions = $state<CatalogRecord[]>([]);
  let categoryOptions = $state<CatalogRecord[]>([]);
  let newAbility = $state('');
  let newPerk = $state('');
  let newCategory = $state('');
  let linking = $state(false);
  let linkError = $state('');
  const endpoint = () => `/api/v1/catalog/${kind}`;
  const singular = $derived(({ roles: 'Role', items: 'Item', abilities: 'Ability', statuses: 'Status', perks: 'Perk', categories: 'Category' })[kind] ?? title);
  function resetDraft() { selected = null; draft = { name: '', description: '', alignment: 'NEUTRAL', rarity: 'COMMON', cost: 0, default_charges: 0, any_ability: false, hour_duration: 0 }; }
  async function load() { loading = true; error = null; try { records = await api.get<CatalogRecord[]>(endpoint()); } catch (e) { error = e instanceof Error ? e.message : `Could not load ${title.toLowerCase()}`; } finally { loading = false; } }
  async function edit(record: CatalogRecord) { try { selected = await api.get<CatalogRecord>(`${endpoint()}/${record.id}`); draft = { name: selected.name, description: selected.description, alignment: selected.alignment ?? 'NEUTRAL', rarity: selected.rarity ?? 'COMMON', cost: selected.cost ?? 0, default_charges: selected.default_charges ?? 0, any_ability: selected.any_ability ?? false, hour_duration: selected.hour_duration ?? 0 }; } catch (e) { error = e instanceof Error ? e.message : 'Could not load record'; } }
  async function loadOptions() { try { if (kind === 'roles') { [abilityOptions, perkOptions] = await Promise.all([api.get<CatalogRecord[]>('/api/v1/catalog/abilities'), api.get<CatalogRecord[]>('/api/v1/catalog/perks')]); } else if (kind === 'items' || kind === 'abilities') { categoryOptions = await api.get<CatalogRecord[]>('/api/v1/catalog/categories'); } } catch { /* options are best-effort */ } }
  async function refreshLinks() { if (selected) try { selected = await api.get<CatalogRecord>(`${endpoint()}/${selected.id}`); } catch (e) { linkError = e instanceof Error ? e.message : 'Could not refresh links'; } }
  async function addLink(target: 'abilities' | 'perks') { if (!selected) return; const name = target === 'abilities' ? newAbility : newPerk; if (!name) return; linking = true; linkError = ''; try { await api.post(`/api/v1/catalog/roles/${selected.id}/${target}`, { body: JSON.stringify(target === 'abilities' ? { ability: name } : { perk: name }), headers: { 'Content-Type': 'application/json' } }); if (target === 'abilities') newAbility = ''; else newPerk = ''; await refreshLinks(); } catch (e) { linkError = e instanceof Error ? e.message : `Could not link ${target === 'abilities' ? 'ability' : 'perk'}`; } finally { linking = false; } }
  async function removeLink(target: 'abilities' | 'perks', item: { id: number; name: string }) { if (!selected || !confirm(`Remove ${item.name} from this role?`)) return; linking = true; linkError = ''; try { await api.delete(`/api/v1/catalog/roles/${selected.id}/${target}/${item.id}`); await refreshLinks(); } catch (e) { linkError = e instanceof Error ? e.message : 'Could not remove link'; } finally { linking = false; } }
  async function addCategory() { if (!selected || !newCategory) return; linking = true; linkError = ''; try { await api.post(`/api/v1/catalog/${kind}/${selected.id}/categories`, { body: JSON.stringify({ category: newCategory }), headers: { 'Content-Type': 'application/json' } }); newCategory = ''; await refreshLinks(); } catch (e) { linkError = e instanceof Error ? e.message : 'Could not assign category'; } finally { linking = false; } }
  async function removeCategory(name: string) { if (!selected || !confirm(`Remove ${name} from this ${singular.toLowerCase()}?`)) return; const cat = categoryOptions.find((c) => c.name === name); if (!cat) { linkError = 'Category record not loaded; refresh the page to remove it.'; return; } linking = true; linkError = ''; try { await api.delete(`/api/v1/catalog/${kind}/${selected.id}/categories/${cat.id}`); await refreshLinks(); } catch (e) { linkError = e instanceof Error ? e.message : 'Could not remove category'; } finally { linking = false; } }
  async function save() { saving = true; error = null; try { const body = kind === 'roles' ? { name: draft.name, description: draft.description, alignment: draft.alignment } : kind === 'items' ? { name: draft.name, description: draft.description, rarity: draft.rarity, cost: draft.cost } : kind === 'abilities' ? { name: draft.name, description: draft.description, rarity: draft.rarity, default_charges: draft.default_charges, any_ability: draft.any_ability } : kind === 'perks' ? { name: draft.name, description: draft.description } : kind === 'categories' ? { name: draft.name } : { name: draft.name, description: draft.description, hour_duration: draft.hour_duration }; if (selected) await api.put<CatalogRecord>(`${endpoint()}/${selected.id}`, { body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } }); else await api.post<CatalogRecord>(endpoint(), { body: JSON.stringify(body), headers: { 'Content-Type': 'application/json' } }); resetDraft(); await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not save record'; } finally { saving = false; } }
  async function remove(record: CatalogRecord) { if (!confirm(`Delete ${record.name}?`)) return; try { await api.delete(`${endpoint()}/${record.id}`); await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not delete record'; } }
  onMount(() => { load(); void loadOptions(); });
  let visibleRecords = $derived((records ?? []).filter((record: CatalogRecord) => { const q = search.trim().toLowerCase(); return !q || `${record.name} ${record.description} ${record.alignment ?? ''} ${record.rarity ?? ''}`.toLowerCase().includes(q); }));
</script>
<svelte:head><title>{title} | Betrayal Admin</title></svelte:head><main class="min-h-screen bg-slate-950 p-6 text-slate-100"><header class="mx-auto max-w-6xl border-b border-slate-700 pb-5"><p class="text-xs font-semibold uppercase tracking-[0.2em] text-slate-400">Catalog administration</p><h1 class="mt-2 text-3xl font-semibold">{title}</h1><p class="mt-2 text-slate-400">Search, inspect, and safely manage the complete {title.toLowerCase()} catalog.</p></header><section class="mx-auto max-w-6xl py-6" aria-label={`${title} editor`}><form class="grid gap-3 rounded border border-slate-800 bg-[#0d111b] p-5 md:grid-cols-2" onsubmit={(event) => { event.preventDefault(); save(); }}><h2 class="md:col-span-2 text-lg">{selected ? `Edit ${singular}` : `New ${singular}`}</h2><input aria-label="Name" bind:value={draft.name} placeholder="Name" required class="bg-slate-900 p-3" />{#if kind !== 'categories'}<input aria-label="Description" bind:value={draft.description} placeholder="Description" class="bg-slate-900 p-3" />{/if}{#if kind === 'roles'}<select aria-label="Alignment" bind:value={draft.alignment} class="bg-slate-900 p-3"><option>GOOD</option><option>NEUTRAL</option><option>EVIL</option></select>{/if}{#if kind === 'items' || kind === 'abilities'}<select aria-label="Rarity" bind:value={draft.rarity} class="bg-slate-900 p-3"><option>COMMON</option><option>UNCOMMON</option><option>RARE</option><option>EPIC</option><option>LEGENDARY</option><option>MYTHICAL</option><option>ROLE_SPECIFIC</option><option>UNIQUE</option></select>{/if}{#if kind === 'items'}<input aria-label="Cost" type="number" bind:value={draft.cost} class="bg-slate-900 p-3" />{/if}{#if kind === 'abilities'}<input aria-label="Default charges" type="number" bind:value={draft.default_charges} class="bg-slate-900 p-3" /><label><input type="checkbox" bind:checked={draft.any_ability} /> Any ability</label>{/if}{#if kind === 'statuses'}<input aria-label="Hour duration" type="number" bind:value={draft.hour_duration} class="bg-slate-900 p-3" />{/if}{#if kind === 'roles' && selected}<div class="md:col-span-2 grid gap-3 rounded border border-slate-800 p-4"><h3 class="text-sm font-semibold uppercase tracking-[0.2em] text-slate-400">Linked abilities</h3>{#each (selected?.abilities ?? []) as ab}<div class="flex items-center justify-between gap-2"><span>{ab.name}</span><button type="button" onclick={() => removeLink('abilities', ab)} class="border border-red-700 px-2 py-1 text-xs text-red-300">Remove</button></div>{/each}<div class="flex gap-2"><select aria-label="Add ability" bind:value={newAbility} class="bg-slate-900 p-2"><option value="">Choose ability…</option>{#each abilityOptions.filter((o) => !(selected?.abilities ?? []).some((l) => l.id === o.id)) as opt}<option value={opt.name}>{opt.name}</option>{/each}</select><button type="button" onclick={() => addLink('abilities')} disabled={linking || !newAbility} class="border border-indigo-600 px-3 py-1 text-indigo-300">Add ability</button></div><h3 class="text-sm font-semibold uppercase tracking-[0.2em] text-slate-400">Linked perks</h3>{#each (selected?.perks ?? []) as pk}<div class="flex items-center justify-between gap-2"><span>{pk.name}</span><button type="button" onclick={() => removeLink('perks', pk)} class="border border-red-700 px-2 py-1 text-xs text-red-300">Remove</button></div>{/each}<div class="flex gap-2"><select aria-label="Add perk" bind:value={newPerk} class="bg-slate-900 p-2"><option value="">Choose perk…</option>{#each perkOptions.filter((o) => !(selected?.perks ?? []).some((l) => l.id === o.id)) as opt}<option value={opt.name}>{opt.name}</option>{/each}</select><button type="button" onclick={() => addLink('perks')} disabled={linking || !newPerk} class="border border-indigo-600 px-3 py-1 text-indigo-300">Add perk</button></div>{#if linkError}<p role="alert" class="text-red-300">{linkError}</p>{/if}</div>{/if}{#if (kind === 'items' || kind === 'abilities') && selected}<div class="md:col-span-2 grid gap-3 rounded border border-slate-800 p-4"><h3 class="text-sm font-semibold uppercase tracking-[0.2em] text-slate-400">Assigned categories</h3>{#each selected.categories ?? [] as cat}<div class="flex items-center justify-between gap-2"><span>{cat}</span><button type="button" onclick={() => removeCategory(cat)} class="border border-red-700 px-2 py-1 text-xs text-red-300">Remove</button></div>{/each}<div class="flex gap-2"><select aria-label="Add category" bind:value={newCategory} class="bg-slate-900 p-2"><option value="">Choose category…</option>{#each categoryOptions.filter((o) => !(selected?.categories ?? []).includes(o.name)) as opt}<option value={opt.name}>{opt.name}</option>{/each}</select><button type="button" onclick={() => addCategory()} disabled={linking || !newCategory} class="border border-indigo-600 px-3 py-1 text-indigo-300">Add category</button></div>{#if linkError}<p role="alert" class="text-red-300">{linkError}</p>{/if}</div>{/if}<div class="md:col-span-2 flex gap-2"><button type="submit" disabled={saving} class="bg-indigo-600 px-4 py-3">{saving ? 'Saving…' : selected ? 'Save changes' : `Create ${singular.toLowerCase()}`}</button>{#if selected}<button type="button" onclick={resetDraft} class="border border-slate-600 px-4 py-3">Cancel</button>{/if}</div></form></section>{#if loading}<p class="mx-auto max-w-6xl py-10 text-slate-300" role="status">Loading {title.toLowerCase()}…</p>{:else if error}<p class="mx-auto max-w-6xl py-10 text-red-300" role="alert">{error}</p>{:else if records}<section class="mx-auto max-w-6xl"><div class="rounded border border-slate-800 bg-[#0d111b] p-4"><input bind:value={search} placeholder={`Search ${title.toLowerCase()} by name, description, or type…`} aria-label={`Search ${title}`} class="w-full bg-slate-900 p-3" /><p class="mt-3 text-sm text-slate-500">Showing {visibleRecords.length} of {records.length}</p></div>{#if visibleRecords.length === 0}<p class="py-10 text-slate-300">No {title.toLowerCase()} match this search.</p>{:else}<div class="mt-4 overflow-x-auto"><table class="w-full text-left" aria-label={title}><thead class="border-b border-slate-700 text-sm uppercase text-slate-400"><tr><th class="p-3">Name</th><th class="p-3">Description</th><th class="p-3">Details</th><th class="p-3">Actions</th></tr></thead><tbody>{#each visibleRecords as record (record.id)}<tr class="border-b border-slate-800"><td class="p-3 font-semibold">{record.name}</td><td class="max-w-md p-3 text-slate-300">{record.description}</td><td class="p-3">{record.alignment ?? record.rarity ?? (record.hour_duration ? `${record.hour_duration}h` : '')}{#if kind === 'roles'} · {record.abilities?.length ?? 0} abilities · {record.perks?.length ?? 0} perks{/if}</td><td class="flex gap-2 p-3"><button type="button" onclick={() => edit(record)} class="border border-slate-600 px-3 py-1">Edit</button><button type="button" onclick={() => remove(record)} class="border border-red-700 px-3 py-1 text-red-300">Delete</button></td></tr>{/each}</tbody></table></div>{/if}</section>{/if}</main>
